__global__ void matmul_kernel_tiled_register_blocking(const float* A, const float* B, float* C, int N) {
    __shared__ float tile_A[TILE_DIM][TILE_DIM];
    __shared__ float tile_B[TILE_DIM][TILE_DIM];

    int block_row = blockIdx.y;
    int block_col = blockIdx.x;

    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int thread_start_row = block_row * TILE_DIM + ty * THREAD_WORK;
    int col = block_col * TILE_DIM + tx;

    float C_sub[THREAD_WORK] = {0.0f};

    for (int t = 0; t < (N + TILE_DIM - 1) / TILE_DIM; ++t) {
        // Load tile of A and B
        for (int i = 0; i < THREAD_WORK; ++i) {
            int a_row = ty * THREAD_WORK + i;
            int a_col = tx;
            int a_global_row = block_row * TILE_DIM + a_row;
            int a_global_col = t * TILE_DIM + a_col;
            if (a_global_row < N && a_global_col < N) {
                tile_A[a_row][a_col] = A[a_global_row * N + a_global_col];
            } else {
                tile_A[a_row][a_col] = 0.0f;
            }
        }

        // Correctly load tile_B. Each thread loads one element.
        int b_row = ty;
        int b_col = tx;
        int b_global_row = t * TILE_DIM + b_row;
        int b_global_col = block_col * TILE_DIM + b_col;
         if (b_global_row < N && b_global_col < N) {
             tile_B[b_row][b_col] = B[b_global_row * N + b_global_col];
        } else {
             tile_B[b_row][b_col] = 0.0f;
        }


        __syncthreads();

        for (int k = 0; k < TILE_DIM; ++k) {
            float b_val = tile_B[k][tx];
            for(int i=0; i<THREAD_WORK; ++i){
                 C_sub[i] += tile_A[ty*THREAD_WORK + i][k] * b_val;
            }
        }
        __syncthreads();
    }

    for(int i=0; i<THREAD_WORK; ++i){
        int c_row = thread_start_row + i;
        if(c_row < N && col < N){
            C[c_row * N + col] = C_sub[i];
        }
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.dim() == 2, "A must be a 2D tensor");
    TORCH_CHECK(B.dim() == 2, "B must be a 2D tensor");
    TORCH_CHECK(A.size(1) == B.size(0), "Matrix dimensions are not compatible for multiplication");

    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    const dim3 blockSize(TILE_DIM, TILE_DIM / THREAD_WORK);
    const dim3 gridSize((N + TILE_DIM - 1) / TILE_DIM, (N + (TILE_DIM) -1) / (TILE_DIM));

    matmul_kernel_tiled_register_blocking<<<gridSize, blockSize>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );

    return C;
}
